public XHTMLContentHandler(ContentHandler handler, Metadata metadata, ParseContext parseContext) {
    super(handler);
    this.metadata = metadata;
    SAXOutputConfig config = parseContext != null ? parseContext.get(SAXOutputConfig.class) : null;
    if (config != null) {
        this.writeMetadataToHead = config.isWriteMetadataToHead();
        this.includeTitle = config.isIncludeTitle();
    } else {
        this.writeMetadataToHead = true;
        this.includeTitle = true;
    }
}
